using System;using System.Drawing;using System.Windows.Forms;using Microsoft.Win32;
namespace ContourWatch {
public static class AgentTheme {
 public static string Preference {get{using(var k=Registry.CurrentUser.OpenSubKey(@"Software\ContourWatch"))return k==null?"system":Convert.ToString(k.GetValue("Theme","system"));}}
 public static bool Dark {get{if(Preference!="system")return Preference=="dark";using(var k=Registry.CurrentUser.OpenSubKey(@"Software\Microsoft\Windows\CurrentVersion\Themes\Personalize"))return k!=null&&Convert.ToInt32(k.GetValue("AppsUseLightTheme",1))==0;}}
 public static void Save(string theme){if(theme!="light"&&theme!="dark"&&theme!="system")throw new ArgumentException("theme");using(var k=Registry.CurrentUser.CreateSubKey(@"Software\ContourWatch"))k.SetValue("Theme",theme);}
 public static void Apply(Control root){root.BackColor=Dark?Color.FromArgb(18,28,30):Color.FromArgb(246,249,247);root.ForeColor=Dark?Color.FromArgb(232,240,236):Color.FromArgb(27,48,41);foreach(Control c in root.Controls){Apply(c);var button=c as Button;if(button!=null){button.FlatStyle=FlatStyle.Flat;button.FlatAppearance.BorderColor=Dark?Color.FromArgb(61,80,77):Color.FromArgb(186,204,193);}if(c is TextBox||c is ComboBox)c.BackColor=Dark?Color.FromArgb(31,45,47):Color.White;}}
 public static ComboBox Picker(Control target){var picker=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Width=210};picker.Items.AddRange(new object[]{"Тема системы","Светлая тема","Тёмная тема"});picker.SelectedIndex=Preference=="dark"?2:Preference=="light"?1:0;picker.SelectedIndexChanged+=(s,e)=>{Save(picker.SelectedIndex==2?"dark":picker.SelectedIndex==1?"light":"system");Apply(target);};return picker;}
 public static void Menu(ContextMenuStrip menu){menu.BackColor=Dark?Color.FromArgb(24,36,38):Color.White;menu.ForeColor=Dark?Color.FromArgb(232,240,236):Color.FromArgb(27,48,41);menu.Renderer=new ToolStripProfessionalRenderer(new Palette());foreach(ToolStripItem item in menu.Items){item.BackColor=menu.BackColor;item.ForeColor=menu.ForeColor;}}
 class Palette:ProfessionalColorTable{public override Color MenuItemSelected{get{return Dark?Color.FromArgb(43,70,62):Color.FromArgb(217,238,226);}}public override Color MenuItemBorder{get{return MenuItemSelected;}}public override Color ToolStripDropDownBackground{get{return Dark?Color.FromArgb(24,36,38):Color.White;}}public override Color ImageMarginGradientBegin{get{return ToolStripDropDownBackground;}}public override Color ImageMarginGradientMiddle{get{return ToolStripDropDownBackground;}}public override Color ImageMarginGradientEnd{get{return ToolStripDropDownBackground;}}}
}
}
